        return account.code.length > 0;
    }

    function internalDelegateCall(
        address target,
        bytes memory data
    ) internal returns (bytes memory) {
        (, bytes memory returndata) = target.delegatecall(data);
        return returndata;
    }

    function privateDelegateCall(
        address target,
        bytes memory data
    ) private returns (bytes memory) {
        (, bytes memory returndata) = target.delegatecall(data);
        return returndata;
    }
}

